u0430\\u043d\\u043d\\u044b\\u0445, (b) \\u0438\\u043d\\u0434\\u0443\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0439 \\u043f\\u0440\\u0435\\u0434\\u0432\\u0437\\u044f\\u0442\\u043e\\u0441\\u0442\\u0438 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438. \\u041d\\u0430 \\u043c\\u0430\\u043b\\u044b\\u0445 N \\u043f\\u0435\\u0440\\u0435\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0441\\u0438\\u043b\\u044c\\u043d\\u0435\\u0435 \\u0443 \\u0433\\u0438\\u0431\\u043a\\u0438\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 (MLP, GP); \\u043d\\u0430 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u0445 N \\u0430\\u0441\\u0438\\u043c\\u043f\\u0442\\u043e\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0441\\u043f\\u0430\\u0434 \\u043e\\u0448\\u0438\\u0431\\u043a\\u0438 \\u043e\\u043f\\u0438\\u0441\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u044b\\u043c \\u0437\\u0430\\u043a\\u043e\\u043d\\u043e\\u043c `MSE \\u221d N^(-\\u03b1)` (\\u043d\\u0435\\u0439\\u0440\\u043e\\u043d\\u043d\\u044b\\u0435 \\u00abscaling laws\\u00bb, Hestness et al. 2017; Kaplan et al. 2020); \\u03b1 \\u0438 \\u0435\\u0433\\u043e \\u0443\\u0441\\u0442\\u043e\\u0439\\u0447\\u0438\\u0432\\u043e\\u0441\\u0442\\u044c \\u0437\\u0430\\u0432\\u0438\\u0441\\u044f\\u0442 \\u043e\\u0442 \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u044b \\u0438 \\u043e\\u0442 \\u0442\\u043e\\u0433\\u043e, \\u043c\\u043e\\u0433\\u0443\\u0442 \\u043b\\u0438 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 inductive biases \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u044c \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0443 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 (\\u0433\\u043b\\u0430\\u0434\\u043a\\u043e\\u0441\\u0442\\u044c \\u043f\\u043e\\u0432\\u0435\\u0440\\u0445\\u043d\\u043e\\u0441\\u0442\\u04