\u0443\\u0449\\u0435\\u0439 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u0438 **\\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442 \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u043b\\u0441\\u044f, \\u0438 \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f \\u0432 \\u0440\\u0430\\u043c\\u043a\\u0430\\u0445 \\u044d\\u0442\\u043e\\u0439 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438** \\u2014 \\u0432\\u0441\\u0435 \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u043e\\u0441\\u0442\\u0430\\u044e\\u0442\\u0441\\u044f \\u043f\\u0443\\u0441\\u0442\\u044b\\u043c\\u0438 \\u043f\\u043e\\u043b\\u044f\\u043c\\u0438 \\u0432 \\u0438\\u0442\\u043e\\u0433\\u043e\\u0432\\u044b\\u0445 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430\\u0445.\", \"evidence\": \"\\u0412\\u0441\\u0435 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b (XGBoost, N_total\\u22484500, T\\u22482500, \\u0441\\u0435\\u0442\\u043a\\u0430 {125, 250, 500, 1000, 2000}, \\u0441\\u0442\\u0440\\u0430\\u0442\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e C) \\u0432\\u0437\\u044f\\u0442\\u044b \\u0438\\u0437 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u0433\\u043e \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f. \\u0421\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430 \\u0432\\u044b\\u0432\\u043e\\u0434\\u0430 (split scheme, HPO, statistical plan, \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u044b, sensitivity, \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f, \\u043e\\u0442\\u043a\\u0430\\u0437 \\u043e\\u0442 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430) \\u044